import React, { useState, useEffect } from "react";
import {
  ShoppingBag, Plus, Trash2, CreditCard, Mail, Tag, X,
  Package, Pencil, ChevronRight, Home as HomeIcon, User, Sparkles,
  LayoutGrid, Send, Users, Info, Gift, Search, Heart, Link2
} from "lucide-react";
import { createClient } from "@supabase/supabase-js";

/* ---------------------------------------------------------
   OLD HABITS — black, tab-based loyalty + shop app
   Tabs: Home / Shop / Points / Profile (+ Manage Store, admin)
   Data persists via Supabase (a real shared database).
--------------------------------------------------------- */

const supabase = createClient(
  import.meta.env.VITE_SUPABASE_URL,
  import.meta.env.VITE_SUPABASE_ANON_KEY
);

const FONT_LINK_ID = "old-habits-fonts";
function useFonts() {
  useEffect(() => {
    if (document.getElementById(FONT_LINK_ID)) return;
    const link = document.createElement("link");
    link.id = FONT_LINK_ID;
    link.rel = "stylesheet";
    link.href = "https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Inter:wght@400;500;600&display=swap";
    document.head.appendChild(link);
  }, []);
}

const LOGO_SRC = "data:image/png;base64,";

const C = {
  bg: "#F4EBD5",
  panel: "#FBF7EC",
  panel2: "#EFE4C8",
  border: "#DCCBA0",
  text: "#171310",
  sub: "#7A6F5C",
  accent: "#9E1F1C", // deep red, dialed back from orange
  accentText: "#F4EBD5", // cream text used on red backgrounds
  danger: "#C4551C",
};

const SEED_PRODUCTS = [
  { id: "p1", name: "Raw Selvedge Jacket", price: 168, category: "Outerwear", swatch: "#3A4A5C", sizes: "S,M,L,XL", stock: 6 },
  { id: "p2", name: "Sun-Faded Chore Coat", price: 142, category: "Outerwear", swatch: "#6C6B47", sizes: "S,M,L", stock: 3 },
  { id: "p3", name: "Rust Canvas Trouser", price: 96, category: "Bottoms", swatch: "#A9541F", sizes: "28,30,32,34,36", stock: 10 },
  { id: "p4", name: "Bone Waffle Henley", price: 54, category: "Tops", swatch: "#D8D2C2", sizes: "S,M,L,XL", stock: 14 },
  { id: "p5", name: "Ink Twill Workshirt", price: 88, category: "Tops", swatch: "#2B2B2B", sizes: "S,M,L,XL", stock: 8 },
];
const SEED_OFFERS = [
  { id: "o1", title: "First Repair, On Us", desc: "New here? Take 15% off your first order.", code: "FIRSTMEND", active: true },
];

const PTS_PER_DOLLAR_EARNED = 5;
const PTS_PER_DOLLAR_REDEEM = 100;
const TIERS = [
  { name: "Apprentice", min: 0, perk: "Member-only offers" },
  { name: "Fitted", min: 500, perk: "Early access to drops" },
  { name: "Tuff", min: 1500, perk: "Free alterations" },
];
function getTierInfo(points) {
  let current = TIERS[0], next = TIERS[1];
  for (let i = 0; i < TIERS.length; i++) if (points >= TIERS[i].min) { current = TIERS[i]; next = TIERS[i + 1] || null; }
  const progress = next ? (points - current.min) / (next.min - current.min) : 1;
  return { current, next, progress: Math.max(0, Math.min(1, progress)) };
}
function currency(n) { return `$${n.toFixed(2)}`; }

async function storageGet(key) {
  try {
    const { data, error } = await supabase.from("app_storage").select("value").eq("key", key).maybeSingle();
    if (error) throw error;
    return data ? data.value : null;
  } catch (e) {
    console.error("storageGet failed for", key, e);
    return null;
  }
}
async function storageSet(key, value) {
  try {
    const { error } = await supabase.from("app_storage").upsert({ key, value, updated_at: new Date().toISOString() });
    if (error) throw error;
  } catch (e) {
    console.error("storageSet failed for", key, e);
  }
}

const ADMIN_PASSWORD_HASH = "6d0c8bc10e5c2b1f71afb42c3ed46ed2b417b85474e0da7a63d424d05cb378e9";

async function sha256(text) {
  const enc = new TextEncoder().encode(text);
  const hashBuffer = await crypto.subtle.digest("SHA-256", enc);
  return Array.from(new Uint8Array(hashBuffer)).map((b) => b.toString(16).padStart(2, "0")).join("");
}

export default function App() {
  useFonts();
  const [section, setSection] = useState("customer"); // customer | manage
  const [adminAuthed, setAdminAuthed] = useState(false);
  const [showAdminGate, setShowAdminGate] = useState(false);
  const [tab, setTab] = useState("home"); // home | shop | points | profile
  const [loaded, setLoaded] = useState(false);

  const [products, setProducts] = useState(SEED_PRODUCTS);
  const [offers, setOffers] = useState(SEED_OFFERS);
  const [subscribers, setSubscribers] = useState([]);
  const [sentNewsletters, setSentNewsletters] = useState([]);
  const [customers, setCustomers] = useState({}); // keyed by phone number — this is the real customer database
  const [squarePaymentLink, setSquarePaymentLink] = useState("");
  const [currentPhone, setCurrentPhone] = useState(null); // who's using the app right now (this session only)
  const [orders, setOrders] = useState([]);

  const [cart, setCart] = useState([]);
  const [cartOpen, setCartOpen] = useState(false);
  const [useCredit, setUseCredit] = useState(false);
  const [useStoreCredit, setUseStoreCredit] = useState(false);
  const [activeProduct, setActiveProduct] = useState(null);
  const [toast, setToast] = useState(null);

  useEffect(() => {
    (async () => {
      const [p, o, s, n, cust, ord, link] = await Promise.all([
        storageGet("oh:products"), storageGet("oh:offers"), storageGet("oh:subscribers"),
        storageGet("oh:newsletters"), storageGet("oh:customers"), storageGet("oh:orders"), storageGet("oh:squareLink"),
      ]);
      if (p) setProducts(p); if (o) setOffers(o); if (s) setSubscribers(s);
      if (n) setSentNewsletters(n); if (cust) setCustomers(cust); if (ord) setOrders(ord);
      if (link) setSquarePaymentLink(link);
      setLoaded(true);
    })();
  }, []);
  useEffect(() => { if (loaded) storageSet("oh:products", products); }, [products, loaded]);
  useEffect(() => { if (loaded) storageSet("oh:offers", offers); }, [offers, loaded]);
  useEffect(() => { if (loaded) storageSet("oh:subscribers", subscribers); }, [subscribers, loaded]);
  useEffect(() => { if (loaded) storageSet("oh:newsletters", sentNewsletters); }, [sentNewsletters, loaded]);
  useEffect(() => { if (loaded) storageSet("oh:customers", customers); }, [customers, loaded]);
  useEffect(() => { if (loaded) storageSet("oh:orders", orders); }, [orders, loaded]);
  useEffect(() => { if (loaded) storageSet("oh:squareLink", squarePaymentLink); }, [squarePaymentLink, loaded]);

  const customer = currentPhone ? customers[currentPhone] : null;

  function enrollOrLogin(name, phone) {
    let isNew = false;
    let newAccountNumber = "";
    setCustomers((cs) => {
      if (cs[phone]) return cs; // already exists, just log them in
      isNew = true;
      const cardLast4 = String(Math.floor(1000 + Math.random() * 9000));
      newAccountNumber = `OH-${String(Object.keys(cs).length + 1).padStart(5, "0")}`;
      return { ...cs, [phone]: { name, phone, points: 0, storeCredit: 0, cardIssued: true, cardLast4, accountNumber: newAccountNumber } };
    });
    setCurrentPhone(phone);
    if (isNew) showToast(`Welcome! Your account number is ${newAccountNumber}`);
  }

  function updateCustomerPoints(phone, deltaFn) {
    setCustomers((cs) => (cs[phone] ? { ...cs, [phone]: { ...cs[phone], points: Math.max(0, deltaFn(cs[phone].points)) } } : cs));
  }

  // Adjusts both points and store credit on one customer in a single update (used at checkout)
  function applyOrderToCustomer(phone, pointsDelta, creditDelta) {
    setCustomers((cs) => {
      if (!cs[phone]) return cs;
      const c = cs[phone];
      return {
        ...cs,
        [phone]: {
          ...c,
          points: Math.max(0, c.points + pointsDelta),
          storeCredit: Math.max(0, +(((c.storeCredit || 0) + creditDelta).toFixed(2))),
        },
      };
    });
  }

  function showToast(msg) {
    setToast(msg);
    window.clearTimeout(showToast._t);
    showToast._t = window.setTimeout(() => setToast(null), 2800);
  }

  function addToCart(product, size) {
    setCart((c) => {
      const existing = c.find((i) => i.id === product.id && i.size === size);
      if (existing) return c.map((i) => (i === existing ? { ...i, qty: i.qty + 1 } : i));
      return [...c, { id: product.id, name: product.name, price: product.price, size, qty: 1 }];
    });
    showToast(`Added ${product.name} (${size}) to your bag`);
    setActiveProduct(null);
    setCartOpen(true);
  }
  function removeFromCart(idx) { setCart((c) => c.filter((_, i) => i !== idx)); }

  const subtotal = cart.reduce((s, i) => s + i.price * i.qty, 0);
  const availableCredit = customer ? customer.points / PTS_PER_DOLLAR_REDEEM : 0;
  const pointsCreditApplied = useCredit ? Math.min(availableCredit, subtotal) : 0;
  const remainingAfterPoints = Math.max(0, subtotal - pointsCreditApplied);
  const storeCreditApplied = useStoreCredit && customer ? Math.min(customer.storeCredit || 0, remainingAfterPoints) : 0;
  const total = Math.max(0, subtotal - pointsCreditApplied - storeCreditApplied);
  const pointsEarnedPreview = Math.round(subtotal * PTS_PER_DOLLAR_EARNED);

  function placeOrder() {
    if (cart.length === 0 || !customer) return;
    const pointsRedeemed = Math.round(pointsCreditApplied * PTS_PER_DOLLAR_REDEEM);
    const pointsEarned = Math.round(subtotal * PTS_PER_DOLLAR_EARNED);
    const order = {
      id: `ord_${Date.now()}`, phone: customer.phone, customerName: customer.name, items: cart, subtotal,
      pointsCreditApplied, storeCreditApplied, total, pointsRedeemed, pointsEarned, date: new Date().toISOString(),
    };
    setOrders((o) => [order, ...o]);
    applyOrderToCustomer(customer.phone, pointsEarned - pointsRedeemed, -storeCreditApplied);
    setCart([]); setUseCredit(false); setUseStoreCredit(false); setCartOpen(false);
    showToast(`Order placed — you earned ${pointsEarned} points`);
  }

  return (
    <div style={{ fontFamily: "'Inter', sans-serif", background: C.bg, color: C.text, minHeight: "100%", width: "100%" }}>
      <style>{`
        .oh-h { font-family: 'Space Grotesk', sans-serif; }
        .oh-btn { transition: transform .12s ease, opacity .15s ease; }
        .oh-btn:active { transform: scale(0.96); }
        .oh-card { transition: border-color .15s ease, transform .15s ease; }
        .oh-card:hover { border-color: #444 !important; transform: translateY(-2px); }
        input, textarea, select { font-family: 'Inter', sans-serif; }
        ::placeholder { color: #6b6b6b; }
        .oh-tab { transition: color .15s ease; }
      `}</style>

      {/* TOP BAR */}
      <div style={{ borderBottom: `1px solid ${C.border}`, position: "sticky", top: 0, zIndex: 20, background: "rgba(244,235,213,0.92)", backdropFilter: "blur(6px)" }}>
        <div style={{ maxWidth: 980, margin: "0 auto", padding: "16px 18px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
          <img src={LOGO_SRC} alt="Old Habits, Utah" style={{ height: 34, width: "auto", display: "block" }} />
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <button onClick={() => { if (section === "customer") { adminAuthed ? setSection("manage") : setShowAdminGate(true); } else { setSection("customer"); } }} className="oh-btn"
              style={{ display: "flex", alignItems: "center", gap: 6, background: "transparent", border: `1px solid ${C.border}`, color: C.sub, padding: "7px 12px", cursor: "pointer", fontSize: 12, borderRadius: 100 }}>
              <LayoutGrid size={13} /> {section === "customer" ? "Manage Store" : "Exit to app"}
            </button>
            {section === "customer" && customer && (
              <button onClick={() => setCartOpen(true)} className="oh-btn" style={{ position: "relative", background: "transparent", border: `1px solid ${C.border}`, borderRadius: 100, width: 36, height: 36, display: "flex", alignItems: "center", justifyContent: "center", cursor: "pointer", color: C.text }}>
                <ShoppingBag size={16} />
                {cart.length > 0 && <span style={{ position: "absolute", top: -4, right: -4, background: C.accent, color: C.accentText, fontSize: 10, fontWeight: 700, width: 16, height: 16, borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center" }}>{cart.reduce((s, i) => s + i.qty, 0)}</span>}
              </button>
            )}
          </div>
        </div>
      </div>

      {section === "customer" ? (
        !customer ? (
          <PhoneGate onSubmit={enrollOrLogin} />
        ) : (
        <>
          <div style={{ maxWidth: 980, margin: "0 auto", paddingBottom: 90 }}>
            {tab === "home" && <HomeTab customer={customer} offers={offers} products={products} onOpenProduct={setActiveProduct} goShop={() => setTab("shop")} showToast={showToast} />}
            {tab === "shop" && <ShopTab products={products} onOpenProduct={setActiveProduct} />}
            {tab === "points" && <PointsTabCustomer customer={customer} />}
            {tab === "profile" && <ProfileTab customer={customer} orders={orders.filter((o) => o.phone === customer.phone)} subscribers={subscribers} setSubscribers={setSubscribers} showToast={showToast} onSwitchAccount={() => setCurrentPhone(null)} />}
          </div>

          {/* BOTTOM NAV */}
          <div style={{ position: "fixed", bottom: 0, left: 0, right: 0, background: "rgba(244,235,213,0.95)", backdropFilter: "blur(8px)", borderTop: `1px solid ${C.border}`, zIndex: 30 }}>
            <div style={{ maxWidth: 980, margin: "0 auto", display: "flex", justifyContent: "space-around", padding: "10px 0 14px" }}>
              {[
                { id: "home", label: "Home", icon: HomeIcon },
                { id: "shop", label: "Shop", icon: Search },
                { id: "points", label: "Points", icon: Sparkles },
                { id: "profile", label: "My Page", icon: User },
              ].map((t) => (
                <button key={t.id} onClick={() => setTab(t.id)} className="oh-btn oh-tab"
                  style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 4, background: "none", border: "none", cursor: "pointer", color: tab === t.id ? C.text : C.sub }}>
                  <t.icon size={20} strokeWidth={tab === t.id ? 2.4 : 1.8} />
                  <span style={{ fontSize: 10.5 }}>{t.label}</span>
                </button>
              ))}
            </div>
          </div>
        </>
        )
      ) : (
        <div style={{ maxWidth: 980, margin: "0 auto", padding: "24px 18px 60px" }}>
          <ManageView
            products={products} setProducts={setProducts}
            offers={offers} setOffers={setOffers}
            subscribers={subscribers}
            customers={customers} setCustomers={setCustomers}
            sentNewsletters={sentNewsletters} setSentNewsletters={setSentNewsletters}
            orders={orders} showToast={showToast}
            squarePaymentLink={squarePaymentLink} setSquarePaymentLink={setSquarePaymentLink}
          />
        </div>
      )}

      {activeProduct && <ProductModal product={activeProduct} onClose={() => setActiveProduct(null)} onAdd={addToCart} />}

      {cartOpen && customer && (
        <div style={{ position: "fixed", inset: 0, zIndex: 40, display: "flex", justifyContent: "flex-end" }}>
          <div onClick={() => setCartOpen(false)} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.6)" }} />
          <div style={{ position: "relative", width: 360, maxWidth: "90vw", background: C.panel, height: "100%", borderLeft: `1px solid ${C.border}`, display: "flex", flexDirection: "column" }}>
            <div style={{ padding: 16, borderBottom: `1px solid ${C.border}`, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
              <div className="oh-h" style={{ fontSize: 16, fontWeight: 700 }}>YOUR BAG</div>
              <button onClick={() => setCartOpen(false)} style={{ background: "none", border: "none", cursor: "pointer", color: C.text }}><X size={20} /></button>
            </div>
            <div style={{ flex: 1, overflowY: "auto", padding: 16 }}>
              {cart.length === 0 && <p style={{ color: C.sub }}>Nothing in your bag yet.</p>}
              {cart.map((item, idx) => (
                <div key={idx} style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 14, paddingBottom: 14, borderBottom: `1px solid ${C.border}` }}>
                  <div>
                    <div style={{ fontWeight: 600 }}>{item.name}</div>
                    <div style={{ fontSize: 13, color: C.sub }}>Size {item.size} · Qty {item.qty}</div>
                  </div>
                  <div style={{ textAlign: "right" }}>
                    <div>{currency(item.price * item.qty)}</div>
                    <button onClick={() => removeFromCart(idx)} style={{ background: "none", border: "none", color: C.danger, cursor: "pointer", fontSize: 12, marginTop: 4 }}>Remove</button>
                  </div>
                </div>
              ))}
            </div>
            <div style={{ padding: 16, borderTop: `1px solid ${C.border}` }}>
              {customer.points > 0 && (
                <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10, fontSize: 13, cursor: "pointer", color: C.sub }}>
                  <input type="checkbox" checked={useCredit} onChange={(e) => setUseCredit(e.target.checked)} />
                  Redeem points ({customer.points.toLocaleString()} pts = {currency(availableCredit)})
                </label>
              )}
              {(customer.storeCredit || 0) > 0 && (
                <label style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, fontSize: 13, cursor: "pointer", color: C.sub }}>
                  <input type="checkbox" checked={useStoreCredit} onChange={(e) => setUseStoreCredit(e.target.checked)} />
                  Use store credit ({currency(customer.storeCredit || 0)} available)
                </label>
              )}
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14, marginBottom: 4, color: C.sub }}><span>Subtotal</span><span>{currency(subtotal)}</span></div>
              {pointsCreditApplied > 0 && <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14, marginBottom: 4, color: C.accent }}><span>Points redeemed</span><span>-{currency(pointsCreditApplied)}</span></div>}
              {storeCreditApplied > 0 && <div style={{ display: "flex", justifyContent: "space-between", fontSize: 14, marginBottom: 4, color: C.accent }}><span>Store credit</span><span>-{currency(storeCreditApplied)}</span></div>}
              <div className="oh-h" style={{ display: "flex", justifyContent: "space-between", fontSize: 18, fontWeight: 700, marginTop: 8, marginBottom: 4 }}><span>Total</span><span>{currency(total)}</span></div>
              {subtotal > 0 && <div style={{ fontSize: 12, color: C.sub, marginBottom: 12 }}>You'll earn {pointsEarnedPreview} points on this order</div>}
              <button disabled={cart.length === 0} onClick={placeOrder} className="oh-btn"
                style={{ width: "100%", padding: "13px", background: cart.length === 0 ? "#333" : C.accent, color: C.accentText, border: "none", borderRadius: 8, cursor: cart.length === 0 ? "not-allowed" : "pointer", fontFamily: "'Space Grotesk', sans-serif", fontWeight: 700, fontSize: 14 }}>
                Place order (demo checkout)
              </button>
              <p style={{ fontSize: 11, color: C.sub, marginTop: 8 }}>Prototype only — no real payment is processed.</p>
            </div>
          </div>
        </div>
      )}

      {showAdminGate && (
        <AdminGate
          onCancel={() => setShowAdminGate(false)}
          onSuccess={() => { setAdminAuthed(true); setShowAdminGate(false); setSection("manage"); }}
        />
      )}

      {toast && (
        <div style={{ position: "fixed", bottom: 90, left: "50%", transform: "translateX(-50%)", background: C.panel2, border: `1px solid ${C.border}`, color: C.text, padding: "10px 18px", fontSize: 14, zIndex: 50, borderRadius: 100, textAlign: "center", maxWidth: "90vw" }}>
          {toast}
        </div>
      )}
    </div>
  );
}

/* ---------------- ADMIN PASSWORD GATE ---------------- */

function AdminGate({ onCancel, onSuccess }) {
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [checking, setChecking] = useState(false);

  async function submit(e) {
    e.preventDefault();
    setChecking(true);
    const hash = await sha256(password);
    setChecking(false);
    if (hash === ADMIN_PASSWORD_HASH) {
      onSuccess();
    } else {
      setError("Incorrect password");
    }
  }

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 60, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
      <div onClick={onCancel} style={{ position: "absolute", inset: 0, background: "rgba(0,0,0,0.5)" }} />
      <div style={{ position: "relative", background: C.panel, border: `1px solid ${C.border}`, borderRadius: 16, maxWidth: 340, width: "100%", padding: 24 }}>
        <div className="oh-h" style={{ fontSize: 17, fontWeight: 700, marginBottom: 6 }}>Staff access</div>
        <p style={{ fontSize: 13, color: C.sub, marginBottom: 16 }}>Enter the store password to manage inventory, customers, and offers.</p>
        <form onSubmit={submit}>
          <input
            type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Password" autoFocus
            style={{ padding: "12px 14px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.panel2, color: C.text, fontSize: 15, width: "100%", marginBottom: 10 }}
          />
          {error && <div style={{ color: C.danger, fontSize: 13, marginBottom: 10 }}>{error}</div>}
          <div style={{ display: "flex", gap: 8 }}>
            <button type="button" onClick={onCancel} className="oh-btn"
              style={{ flex: 1, padding: 12, background: "transparent", border: `1px solid ${C.border}`, color: C.text, borderRadius: 10, cursor: "pointer", fontWeight: 600 }}>
              Cancel
            </button>
            <button type="submit" disabled={checking} className="oh-btn"
              style={{ flex: 1, padding: 12, background: C.accent, color: C.accentText, border: "none", borderRadius: 10, cursor: checking ? "wait" : "pointer", fontFamily: "'Space Grotesk', sans-serif", fontWeight: 700, opacity: checking ? 0.7 : 1 }}>
              {checking ? "Checking..." : "Unlock"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

/* ---------------- PHONE GATE (sign in / enroll) ---------------- */

function PhoneGate({ onSubmit }) {
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [error, setError] = useState("");

  function submit(e) {
    e.preventDefault();
    const digits = phone.replace(/\D/g, "");
    if (digits.length < 7) return setError("Enter a valid phone number");
    if (!name.trim()) return setError("Enter your name");
    setError("");
    onSubmit(name.trim(), digits);
  }

  return (
    <div style={{ minHeight: "70vh", display: "flex", alignItems: "center", justifyContent: "center", padding: "40px 18px" }}>
      <div style={{ maxWidth: 360, width: "100%", textAlign: "center" }}>
        <img src={LOGO_SRC} alt="Old Habits, Utah" style={{ height: 84, width: "auto", marginBottom: 20 }} />
        <h1 className="oh-h" style={{ fontSize: 22, fontWeight: 700, margin: "0 0 6px" }}>Welcome to Old Habits</h1>
        <p style={{ color: C.sub, fontSize: 14, marginBottom: 22 }}>Enter your phone number to check your points, or join if you're new.</p>
        <form onSubmit={submit} style={{ display: "flex", flexDirection: "column", gap: 10, textAlign: "left" }}>
          <div>
            <div style={{ fontSize: 12, color: C.sub, marginBottom: 6, fontWeight: 600 }}>NAME</div>
            <input value={name} onChange={(e) => setName(e.target.value)} placeholder="Your name"
              style={{ padding: "12px 14px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.panel, color: C.text, fontSize: 15, width: "100%" }} />
          </div>
          <div>
            <div style={{ fontSize: 12, color: C.sub, marginBottom: 6, fontWeight: 600 }}>PHONE NUMBER</div>
            <input value={phone} onChange={(e) => setPhone(e.target.value)} placeholder="(555) 555-5555" type="tel"
              style={{ padding: "12px 14px", borderRadius: 10, border: `1px solid ${C.border}`, background: C.panel, color: C.text, fontSize: 15, width: "100%" }} />
          </div>
          {error && <div style={{ color: C.danger, fontSize: 13 }}>{error}</div>}
          <button type="submit" className="oh-btn" style={{ marginTop: 8, padding: 14, background: C.accent, color: C.accentText, border: "none", borderRadius: 10, cursor: "pointer", fontFamily: "'Space Grotesk', sans-serif", fontWeight: 700, fontSize: 15 }}>
            Continue
          </button>
        </form>
        <p style={{ fontSize: 11.5, color: C.sub, marginTop: 16 }}>New here? Continuing creates your account automatically — no password needed.</p>
      </div>
    </div>
  );
}

